	"fyne.io/fyne/v2/storage"
)

// NewSprintf creates a String binding that formats multiple data sources using fmt.Sprintf.
// When any source binding changes, the formatted string is automatically updated.
// Set() parses the string back using fmt.Sscanf and updates source bindings.
//
// Since: 2.5
func NewSprintf(format string, bindings ...DataItem) String {
	if len(bindings) == 0 {
		return NewString()
	}

	s := &sprintfString{
		format:   format,
		bindings: bindings,
	}
	s.ExtendBase(s)

	// Connect to all source bindings
	listener := NewDataListener(func() {
		s.lock.Lock()
		defer s.lock.Unlock()
		s.updateFormatted()
		s.trigger()
	})

	for _, b := range bindings {
		b.AddListener(listener)
	}

	// Initial format
	s.updateFormatted()

	return s
}

// StringToStringWithFormat wraps a String binding with a format string.
// If format is "%s", returns the original binding directly.
//
// Since: 2.5
func StringToStringWithFormat(str String, format string) String {
	if format == "%s" {
		return str
	}
	return NewSprintf(format, str)
}

type sprintfString struct {
	base

	format   string
	bindings []DataItem
	value    string
	lastErr  error
}

func (s *sprintfString) updateFormatted() {
	// Called with lock held
	values := make([]interface{}, len(s.bindings))
	s.lastErr = nil

	for i, b := range s.bindings {
		var err error
		switch typed := b.(type) {
		case Bool:
			values[i], err = typed.Get()
		case Bytes:
			values[i], err = typed.Get()
		case Float:
			values[i], err = typed.Get()
		case Int:
			values[i], err = typed.Get()
		case Rune:
			values[i], err = typed.Get()
		case String:
			values[i], err = typed.Get()
		case URI:
			var u fyne.URI
			u, err = typed.Get()
			if err == nil && u != nil {
				values[i] = u.String()
			} else {
				values[i] = ""
			}
		case Untyped:
			values[i], err = typed.Get()
		default:
			err = fmt.Errorf("unsupported binding type")
		}

		if err != nil {
			s.lastErr = err
			return
		}
	}

	s.value = fmt.Sprintf(s.format, values...)
}

func (s *sprintfString) Get() (string, error) {
	s.lock.RLock()
	defer s.lock.RUnlock()

	if s.lastErr != nil {
		return "", s.lastErr
	}
	return s.value, nil
}

func (s *sprintfString) Set(val string) error {
	s.lock.Lock()
	defer s.lock.Unlock()

	// Parse the string back into individual values
	values := make([]interface{}, len(s.bindings))
	for i, b := range s.bindings {
		switch b.(type) {
		case Bool:
			var v bool
			values[i] = &v
		case Bytes:
			// Bytes cannot be round-tripped via Sscanf
			return fmt.Errorf("cannot parse Bytes binding from formatted string")
		case Float:
			var v float64
			values[i] = &v
		case Int:
			var v int
			values[i] = &v
		case Rune:
			var v rune
			values[i] = &v
		case String:
			var v string
			values[i] = &v
		case URI:
			var v string
			values[i] = &v
		case Untyped:
			var v interface{}
			values[i] = &v
		}
	}

	// Parse using Sscanf
	n, err := fmt.Sscanf(val, s.format, values...)
	if err != nil {
		return err
	}
	if n != len(s.bindings) {
		return fmt.Errorf("format matched %d values, expected %d", n, len(s.bindings))
	}

	// Set parsed values back to bindings
	for i, b := range s.bindings {
		var setErr error
		switch typed := b.(type) {
		case Bool:
			setErr = typed.Set(*values[i].(*bool))
		case Float:
			setErr = typed.Set(*values[i].(*float64))
		case Int:
			setErr = typed.Set(*values[i].(*int))
		case Rune:
			setErr = typed.Set(*values[i].(*rune))
		case String:
			setErr = typed.Set(*values[i].(*string))
		case URI:
			uriStr := *values[i].(*string)
			uri, parseErr := storage.ParseURI(uriStr)
			if parseErr != nil {
				setErr = parseErr
			} else {
				setErr = typed.Set(uri)
			}
		case Untyped:
			setErr = typed.Set(*values[i].(*interface{}))
		}

		if setErr != nil {
			return setErr
		}
	}

	return nil
}

package validation

import "fmt"

// AllValid returns a validator that chains multiple validators together.
// It passes only if all child validators pass. Errors are accumulated and reported together.
//
// Since: 2.5
func AllValid(validators ...Validator) Validator {
	return &allValidator{validators: validators}
}

type allValidator struct {
	validators []Validator
}

func (v *allValidator) Validate(value interface{}) error {
	var errors []error

	for _, validator := range v.validators {
		if err := validator.Validate(value); err != nil {
			errors = append(errors, err)
		}
	}

	if len(errors) == 0 {
		return nil
	}

	if len(errors) == 1 {
		return errors[0]
	}

	// Combine multiple errors
	errMsg := "validation failed:"
	for i, err := range errors {
		errMsg += fmt.Sprintf("\n  %d. %s", i+1, err.Error())
	}

	return fmt.Errorf(errMsg)
}

