type Validator interface {
	Validate(interface{}) error
}

// NewAllStrings returns a StringValidator that chains multiple string validators together.
// It runs all validators in order and returns the first error encountered.
// If all validators pass, it returns nil.
//
// Since: 2.5
func NewAllStrings(validators ...fyne.StringValidator) fyne.StringValidator {
	return func(text string) error {
		for _, validator := range validators {
			if err := validator(text); err != nil {
				return err
			}
		}
		return nil
	}
}

